191	function claimCreatorCloseRegistration(plane: V3PlaneHandle): V3CreatorCloseRegistration | undefined {
192		const registration = creatorCloseRegistrationResolver?.(plane);
193		return plainRecord(registration) ? (registration as unknown as V3CreatorCloseRegistration) : undefined;
194	}
195	
196	function verifiedCreatorTrustRecord(
197		registration: V3CreatorCloseRegistration,
198		exactCanonicalTrustStateRecordBytes: Uint8Array
199	): Readonly<Record<string, unknown>> | undefined {
200		try {
201			const record = decodeCanonical(exactCanonicalTrustStateRecordBytes);
202			if (!plainRecord(record) || !(record.exactCanonicalSignerSetBytes instanceof Uint8Array)) return undefined;
203			const signerSet = decodeCanonical(record.exactCanonicalSignerSetBytes);
204			return record.currentAnchorDigest === registration.currentTrust.currentAnchorDigest &&
205				record.currentEpoch === registration.currentTrust.currentEpoch &&
206				record.genesisAnchorDigest === registration.currentTrust.genesisAnchorDigest &&
207				record.objectId === registration.currentTrust.objectId &&
208				record.profileId === registration.currentTrust.profileId &&
209				record.profileId === "creator-trusted-v1" &&
210				record.quorum === 1 &&
211				Array.isArray(signerSet) &&
212				signerSet.length === 1
213				? record
214				: undefined;
215		} catch {
216			return undefined;
217		}
218	}
219	
220	function copiedRef(ref: GenerationRef): GenerationRef {
221		return Object.freeze({ byteLength: ref.byteLength, digest: ref.digest });
222	}
223	
224	function compareRef(left: GenerationRef, right: GenerationRef): number {
225		return left.digest < right.digest ? -1 : left.digest > right.digest ? 1 : 0;
226	}
227	
228	function plainRecord(value: unknown): value is Readonly<Record<string, unknown>> {
229		return value !== null && typeof value === "object" && !Array.isArray(value);
230	}
231	
232	function successfulValue<T>(value: unknown): T | undefined {
233		if (!plainRecord(value) || value.ok !== true || !Object.hasOwn(value, "value")) return undefined;
234		return value.value as T;
235	}
236	
237	function successfulUndefined(value: unknown): boolean {
238		return plainRecord(value) && value.ok === true && Object.hasOwn(value, "value") && value.value === undefined;
239	}
240	
241	function refFor(bytes: Uint8Array): GenerationRef {
242		const digest = digestBlob(bytes);
243		if (!digest.ok) throw new TypeError("creator close blob digest failed");
244		return Object.freeze({ byteLength: bytes.byteLength, digest: digest.value });
245	}
246	
247	function sameRef(left: GenerationRef, right: GenerationRef): boolean {
248		return left.byteLength === right.byteLength && left.digest === right.digest;
249	}
250	
251	function hex(bytes: Uint8Array): string {
252		return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
253	}
254	
255	type InspectedHead = Awaited<ReturnType<typeof inspectHead>>;
256	
257	function uniqueRecordCandidate(
258		candidates: InspectedHead["candidates"],
259		kind: string,
260		epoch?: number,
261		phase?: string
262	): InspectedHead["candidates"][number] | undefined {
263		const matches = candidates.filter((candidate) => {
264			try {
265				const value = decodeCanonical(candidate.bytes);
266				const selectedEpoch =
267					plainRecord(value) &&
268					(value.kind === "drp-anchor-trust-state"
269						? value.currentEpoch
270						: value.kind === CREATOR_ISSUANCE_RETIREMENT_KIND || value.kind === CREATOR_AUTHOR_ISSUANCE_FRONTIERS_KIND
271							? value.closedEpoch
272							: value.epoch);
273				return (
274					plainRecord(value) &&
275					value.kind === kind &&
276					(epoch === undefined || selectedEpoch === epoch) &&
277					(phase === undefined || value.phase === phase)
278				);
279			} catch {
280				return false;
281			}
282		});
283		return matches.length === 1 ? matches[0] : undefined;
284	}
285	
286	async function issuanceRetirementCandidate(
287		input: Readonly<{
288			current: InspectedHead;
289			currentTrust: CurrentAnchorTrust;
290			cutValueDigest: string;
291			durableReplay: Readonly<{ verify(): Promise<boolean> }>;
292			graph: Exclude<ReturnType<V3CreatorCloseRegistration["captureCloseGraph"]>, undefined>;
293			issuanceScope: DurableIssueScope;
294			issuanceStore: DurableIssuanceStore;
295			maxEpochVertices: number;
296			qcRef: GenerationRef;
297			signer: FinalitySigner;
298			snapshotManifestDigest: string;
299			successorTrust: CurrentAnchorTrust;
300		}>
301	): Promise<
302		Readonly<{
303			admittedAuthorSequence: number;
304			author: string;
305			bytes: Uint8Array;
306			priorRef?: GenerationRef;
307			ref: GenerationRef;
308		}>
309	> {
310		if (!(await input.durableReplay.verify())) throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
311		let priorAdmittedAuthorSequence: number | null = null;
312		let priorRetirementCandidateDigest = CREATOR_ISSUANCE_RETIREMENT_GENESIS_SENTINEL;
313		let priorRef: GenerationRef | undefined;
314		if (input.currentTrust.currentEpoch > 0) {
315			const candidate = uniqueRecordCandidate(input.current.candidates, CREATOR_ISSUANCE_RETIREMENT_KIND);
316			const cut = uniqueRecordCandidate(
317				input.current.candidates,
318				"drp-hard-epoch-cut",
319				input.currentTrust.currentEpoch - 1
320			);
321			const qc = uniqueRecordCandidate(
322				input.current.candidates,
323				"drp-seal-qc",
324				input.currentTrust.currentEpoch - 1,
325				"commit"
326			);
327			if (candidate === undefined || cut === undefined || qc === undefined) {
328				throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
329			}
330			const cutRecord = decodeCanonical(cut.bytes);
331			if (!plainRecord(cutRecord) || typeof cutRecord.snapshotManifestDigest !== "string") {
332				throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
333			}
334			const opened = openCreatorIssuanceRetirement({
335				exactCanonicalRecordBytes: candidate.bytes,
336				expectedCommitQcRef: qc.ref,
337				expectedCutValueDigest: hex(hashDomain("ts-drp/hard-epoch-cut/v3", cut.bytes)),
338				expectedSnapshotManifestDigest: cutRecord.snapshotManifestDigest,
339				floorTrust: input.currentTrust,
340			});
341			const identity = opened.ok ? resolveCreatorIssuanceRetirement(opened.capability) : undefined;
342			if (identity === undefined || identity.author !== input.issuanceScope.author) {
343				throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
344			}
345			priorAdmittedAuthorSequence = identity.admittedAuthorSequence;
346			priorRetirementCandidateDigest = candidate.ref.digest;
347			priorRef = candidate.ref;
348		}
349		const boundary = await deriveCreatorIssuanceRetirementBoundary({
350			currentAnchorDigest: input.currentTrust.currentAnchorDigest,
351			currentEpoch: input.currentTrust.currentEpoch,
352			graphVertexDigests: input.graph.vertices,
353			issuanceScope: input.issuanceScope,
354			issuanceStore: input.issuanceStore,
355			maxEpochVertices: input.maxEpochVertices,
356			priorAdmittedAuthorSequence,
357		});
358		const prepared = prepareCreatorIssuanceRetirement({
359			admittedAuthorSequence: boundary.admittedAuthorSequence,
360			author: input.issuanceScope.author,
361			commitQcRef: input.qcRef,
362			currentTrust: input.currentTrust,
363			cutValueDigest: input.cutValueDigest,
364			observedLineage: boundary.observedLineage,
365			priorAdmittedAuthorSequence,
366			priorRetirementCandidateDigest,
367			snapshotManifestDigest: input.snapshotManifestDigest,
368			successorTrust: input.successorTrust,
369		});
370		if (!prepared.ok) throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
371		const signature = await signCreatorIssuanceRetirementRequest({
372			request: prepared.signingRequest,
373			signer: input.signer,
374		});
375		const completed = completeCreatorIssuanceRetirement({
376			detachedSignature: signature,
377			preparation: prepared.preparation,
378		});
379		if (!completed.ok) throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
380		const ref = refFor(completed.exactCanonicalRecordBytes);
381		return Object.freeze({
382			admittedAuthorSequence: boundary.admittedAuthorSequence,
383			author: input.issuanceScope.author,
384			bytes: Uint8Array.from(completed.exactCanonicalRecordBytes),
385			...(priorRef === undefined ? {} : { priorRef: copiedRef(priorRef) }),
386			ref,
387		});
388	}
389	
390	function openedLatchedAcl(
391		exactCanonicalLatchedAclBytes: Uint8Array,
392		trust: CurrentAnchorTrust,
393		expectedAclDigest: string
394	): LatchedAclSnapshot | undefined {
395		const opened = openCanonicalLatchedAclSnapshot({
396			exactCanonicalLatchedAclBytes,
397			expectedAclDigest,
398			expectedEpoch: trust.currentEpoch,
399			expectedObjectId: trust.objectId,
400		});
401		return opened.ok ? opened.snapshot : undefined;
402	}
403	
404	function writeAuthorizedAuthors(snapshot: LatchedAclSnapshot): readonly string[] | undefined {
405		const selected: string[] = [];
406		for (const member of snapshot.members) {
407			const authorized = authorizeLatchedApplicationWrite({ author: member.author, snapshot });
408			if (!authorized.ok) return undefined;
409			if (authorized.authorized) selected.push(member.author);
410		}
411		return Object.freeze(selected.sort());
412	}
413	
414	function candidateAclDigest(candidate: Readonly<{ readonly bytes: Uint8Array }>): string {
415		return hex(hashDomain("ts-drp/latched-acl/v3", candidate.bytes));
416	}
417	
418	async function authorIssuanceFrontiersCandidate(
419		input: Readonly<{
420			current: InspectedHead;
421			currentAclDigest: string;
422			currentExactAclBytes: Uint8Array;
423			currentTrust: CurrentAnchorTrust;
424			cutValueDigest: string;
425			graph: Exclude<ReturnType<V3CreatorCloseRegistration["captureCloseGraph"]>, undefined>;
426			issuanceScope: DurableIssueScope;
427			issuanceStore: DurableIssuanceStore;
428			legacy: Awaited<ReturnType<typeof issuanceRetirementCandidate>>;
429			qcRef: GenerationRef;
430			signer: FinalitySigner;
431			snapshotManifestDigest: string;
432			successorAclDigest: string;
433			successorExactAclBytes: Uint8Array;
434			successorTrust: CurrentAnchorTrust;
435		}>
436	): Promise<Readonly<{ bytes: Uint8Array; priorRef?: GenerationRef; ref: GenerationRef }>> {
437		const currentAcl = openedLatchedAcl(input.currentExactAclBytes, input.currentTrust, input.currentAclDigest);
438		const successorAcl = openedLatchedAcl(input.successorExactAclBytes, input.successorTrust, input.successorAclDigest);
439		const successorAuthors = successorAcl === undefined ? undefined : writeAuthorizedAuthors(successorAcl);
440		if (currentAcl === undefined || successorAcl === undefined || successorAuthors === undefined) {
441			throw new TypeError("creator issuance-frontier ACL authority is unavailable");
442		}
443	
444		const aggregateCandidates = input.current.candidates.filter((candidate) => {
445			try {
446				return (
447					(decodeCanonical(candidate.bytes) as Readonly<Record<string, unknown>>)?.kind ===
448					CREATOR_AUTHOR_ISSUANCE_FRONTIERS_KIND
449				);
450			} catch {
451				return false;
452			}
453		});
454		if (aggregateCandidates.length > 1 || (input.currentTrust.currentEpoch === 0 && aggregateCandidates.length !== 0)) {
455			throw new TypeError("creator issuance-frontier candidate is ambiguous");
456		}
457		let priorIdentity: ReturnType<typeof resolveCreatorAuthorIssuanceFrontiers>;
458		let priorRef: GenerationRef | undefined;
459		if (aggregateCandidates.length === 1) {
460			const candidate = aggregateCandidates[0] as (typeof aggregateCandidates)[number];
461			const closedEpoch = input.currentTrust.currentEpoch - 1;
462			const cut = uniqueRecordCandidate(input.current.candidates, "drp-hard-epoch-cut", closedEpoch);
463			const qc = uniqueRecordCandidate(input.current.candidates, "drp-seal-qc", closedEpoch, "commit");
464			const acl = uniqueRecordCandidate(input.current.candidates, "drp-v3-latched-acl", closedEpoch);
465			const cutRecord = cut === undefined ? undefined : decodeCanonical(cut.bytes);
466			if (cut === undefined || qc === undefined || acl === undefined || !plainRecord(cutRecord)) {
467				throw new TypeError("creator issuance-frontier predecessor proof is unavailable");
468			}
469			const opened = openCreatorAuthorIssuanceFrontiers({
470				exactCanonicalRecordBytes: candidate.bytes,
471				expectedCommitQcRef: qc.ref,
472				expectedCurrentAclDigest: candidateAclDigest(acl),
473				expectedCutValueDigest: hex(hashDomain("ts-drp/hard-epoch-cut/v3", cut.bytes)),
474				expectedSnapshotManifestDigest: cutRecord.snapshotManifestDigest,
475				expectedSuccessorAclDigest: input.currentAclDigest,
476				floorTrust: input.currentTrust,
477			});
478			priorIdentity = opened.ok ? resolveCreatorAuthorIssuanceFrontiers(opened.capability) : undefined;
479			if (priorIdentity === undefined) {
480				throw new TypeError("creator issuance-frontier predecessor proof is invalid");
481			}
482			priorRef = candidate.ref;
483		}
484	
485		const byAuthor = new Map<string, number[]>();
486		const duplicateAuthors = new Set<string>();
487		for (const identity of input.graph.authors.values()) {
488			const sequences = byAuthor.get(identity.author) ?? [];
489			if (sequences.includes(identity.authorSequence)) {
490				if (identity.author === input.issuanceScope.author) {
491					throw new TypeError("creator issuance-frontier author slot is ambiguous");
492				}
493				duplicateAuthors.add(identity.author);
494				continue;
495			}
496			sequences.push(identity.authorSequence);
497			byAuthor.set(identity.author, sequences);
498		}
499		for (const sequences of byAuthor.values()) sequences.sort((left, right) => left - right);
500	
501		const prior = new Map(priorIdentity?.frontiers ?? []);
502		let localNext: number | undefined;
503		if (successorAuthors.includes(input.issuanceScope.author)) {
504			const lineage = await input.issuanceStore.readLineage(input.issuanceScope);
505			if (lineage.exhausted !== false || !Number.isSafeInteger(lineage.next) || lineage.next < 0) {
506				throw new TypeError("creator issuance-frontier local lineage is invalid");
507			}
508			localNext = lineage.next;
509		}
510		const frontiers: CreatorAuthorIssuanceFrontier[] = [];
511		for (const author of successorAuthors) {
512			const priorBoundary = prior.get(author);
513			const sequences = byAuthor.get(author) ?? [];
514			if (priorIdentity === undefined && author === input.legacy.author) {
515				frontiers.push(Object.freeze([author, input.legacy.admittedAuthorSequence] as const));
516				continue;
517			}
518			if (priorBoundary === undefined) {
519				const observedNext = author === input.issuanceScope.author ? localNext : undefined;
520				if ((sequences[0] ?? observedNext ?? 0) > 1) {
521					throw new TypeError(
522						priorIdentity === undefined ? LEGACY_MULTI_AUTHOR_MIGRATION_REQUIRED : AUTHOR_REENTRY_PROOF_REQUIRED
523					);
524				}
525			}
526			let boundary = priorBoundary ?? null;
527			const firstObserved = sequences[0];
528			if (duplicateAuthors.has(author)) {
529				frontiers.push(Object.freeze([author, boundary] as const));
530				continue;
531			}
532			if (boundary === null && firstObserved !== undefined && firstObserved > 1) {
533				if (author === input.issuanceScope.author) {
